def rule_fn(row, col):
    if col != 'Stateavg':
        return False
    s = str(row.get('Stateavg', '')).strip()
    st = str(row.get('State', '')).strip().lower()
    if '_' not in s or not st:
        return True
    prefix = s.split('_', 1)[0].lower()
    return prefix != st

