def rule_fn(row, col):
    text_cols = {'HospitalName','Address','City','CountyName','MeasureName'}
    if col not in text_cols:
        return False
    import re
    val = str(row.get(col, '')).strip()
    tokens = re.findall(r'[A-Za-z]+', val)
    whitelist = {'next','exercise','exercises','example','examples','annex','complex','index','indexes','box','boxes','oxide'}
    for tok in tokens:
        tl = tok.lower()
        if 'x' in tl and tl not in whitelist:
            return True
    return False
